-- Upserts the avatar v2 catalog. Safe to run repeatedly.
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM public.avatar_items WHERE art_version = 1 AND item_key IN ('base_body', 'bone_crown', 'brows_arched', 'brows_scowl', 'brows_soft', 'brows_thick', 'buckle_boots', 'charm_choker', 'coffin_backpack', 'eyes_button', 'eyes_cat_slits', 'eyes_hollow', 'eyes_sharp_glare', 'eyes_sleepless', 'eyes_wide', 'grave_creepers', 'grave_tee', 'grave_wraps', 'gravewarden_cloak', 'graveyard_mist', 'hair_banshee_mane', 'hair_ghoul_mop', 'hair_grave_crop', 'hair_long_wisp', 'hair_spider_buns', 'hair_undertaker_sweep', 'hex_stockings', 'katana_back', 'katana_drawn', 'moth_wings', 'mouth_blep', 'mouth_fang', 'mouth_frown', 'mouth_jack_grin', 'mouth_smile', 'mouth_smirk', 'mouth_stitched', 'paint_blush', 'paint_freckles', 'paint_ink_tears', 'paint_skull', 'paint_stitches', 'patched_trousers', 'plague_mask', 'porcelain_mask', 'pumpkin_head', 'ram_horns', 'raven_familiar', 'reaper_scythe', 'soul_lantern', 'stitchwork_sweater', 'tattered_bat_wings', 'tattered_skirt', 'undertaker_coat', 'witch_hat')) THEN
